        "prompt":  "Technical Packaging Design Presentation Template\nTemplate Name: Technical Packaging Design Presentation Template\n\nPrompt Template:\n\n{\n\n  \"user_input\": {\n\n    \"product_type\": \"[PRODUCT_TYPE_DESCRIPTION]\",\n\n    \"package_format\": \"[PACKAGE_SHAPE_AND_STRUCTURE]\",\n\n    \"brand_name\": \"[BRAND_NAME]\",\n\n    \"variant_name\": \"[PRODUCT_VARIANT_NAME]\",\n\n    \"primary_package_color\": \"[PRIMARY_COLOR]\",\n\n    \"secondary_package_color\": \"[SECONDARY_COLOR]\",\n\n    \"closure_or_top_detail\": \"[CLOSURE_MECHANISM_AND_MATERIAL]\",\n\n    \"key_visual_element\": \"[MAIN_ILLUSTRATION_OR_GRAPHIC_ELEMENTS]\",\n\n    \"required_label_sections\": \"[LIST_OF_LABEL_CONTENT_SECTIONS]\",\n\n    \"presentation_views\": \"[SPECIFIC_MOCKUP_ANGLES]\",\n\n    \"technical_annotations\": \"[LIST_OF_TECHNICAL_DETAILS_TO_SHOW]\",\n\n    \"background_style\": \"[BACKGROUND_FOR_TECHNICAL_AND_MOCKUP]\",\n\n    \"label_language\": \"[LANGUAGE_SPECIFICATION]\"\n\n  },\n\n  \"poster_type\": \"packaging design technical presentation\",\n\n  \"style\": \"professional industrial design presentation combining flat technical layout and realistic product mockup\",\n\n  \"context\": \"A packaging presentation board showing structural artwork planning together with final product visualization\",\n\n  \"language_rules\": {\n\n    \"default_language\": \"[LANGUAGE_SPECIFICATION]\",\n\n    \"all_visible_label_text_must_be_correct\": true,\n\n    \"grammar_must_be_correct\": true,\n\n    \"no_garbled_text\": true,\n\n    \"no_mixed_language_unless_requested\": true,\n\n    \"critical_text_rule\": \"Any text generated or expanded by the model must be fully legible, naturally phrased, and spelled exactly correctly with no mistakes.\"\n\n  },\n\n  \"composition\": {\n\n    \"layout_structure\": \"Split presentation with a technical planning section and a realistic mockup section\",\n\n    \"backgrounds\": {\n\n      \"technical_section\": \"Use a clean technical background based on background_style\",\n\n      \"mockup_section\": \"Use a clean studio-style presentation background\"\n\n    }\n\n  },\n\n  \"technical_section\": {\n\n    \"description\": \"Show flat packaging artwork, layout, dieline, or structural planning appropriate to package_format\",\n\n    \"details\": \"Only include technical marks, dimensions, folds, cuts, glue areas, or annotations if specified in technical_annotations\",\n\n    \"artwork_content\": \"Display flat artwork using brand_name, variant_name, key_visual_element, package colors, and required_label_sections\",\n\n    \"text_accuracy_rule\": \"All text in the technical section must be fully legible, correctly spelled, professionally typeset, and logically appropriate to the product.\"\n\n  },\n\n  \"mockup_section\": {\n\n    \"description\": \"Show realistic product mockups based on package_format and presentation_views\",\n\n    \"material_logic\": \"Material, finish, and structure must match the selected product_type and package_format\",\n\n    \"label_logic\": \"Visible label sections must follow required_label_sections only, while allowing the model to intelligently format and expand them into realistic packaging text when needed.\",\n\n    \"text_accuracy_rule\": \"All text on the final mockup must remain sharp, readable, logically written, correctly spelled, and consistent with the product identity and flat artwork.\",\n\n    \"internal_arrangement\": \"Inside the box, neatly arrange [PRODUCT_CONTENTS_DESCRIPTION], each placed in custom-fit compartments with premium presentation.\"\n\n  },\n\n  \"font_logic\": {\n\n    \"font_style\": \"clean professional packaging typography\",\n\n    \"headline_font\": \"beautiful display font with strong readability and commercial packaging appeal\",\n\n    \"supporting_font\": \"clean sans-serif or editorial font for details and product information\",\n\n    \"technical_font\": \"precise readable font for annotation and specification text\",\n\n    \"rules\": [\n\n      \"Typography must look intentional and professional\",\n\n      \"Maintain proper spacing and line breaks\",\n\n      \"Important information must stay easy to read\"\n\n    ]\n\n  },\n\n  \"restrictions\": {\n\n    \"do_not_assume_wrong_category\": true,\n\n    \"do_not_assume_unrequested_formats\": true,\n\n    \"do_not_add_unrequested_label_sections\": true,\n\n    \"no_random_text\": true,\n\n    \"no_placeholder_tokens_visible\": true,\n\n    \"no_spelling_errors\": true,\n\n    \"no_watermark\": true\n\n  }\n\n}",
