        "prompt":  "\n\n{\n  \"system_core\": {\n    \"mode\": \"Hybrid Professional Studio\",\n    \"quality_standard\": \"Commercial Masterpiece\",\n    \"fail_safe_mechanism\": \"ALWAYS override bad user inputs with professional aesthetic rules.\"\n  },\n\n  \"user_inputs\": {\n    \"source_image\": \"{UPLOAD_IMAGE_OR_NULL}\",\n    \"dish_name\": \"{argument name=\\\"dish_name\\\" description=\\\"Dish name (Used if no image)\\\" default=\\\"\\\"}\",\n    \"mood_tone\": \"{argument name=\\\"mood_tone\\\" description=\\\"Optional vibe (e.g., Luxury, Morning). Defaults to \u0027Gourmet\u0027.\\\" default=\\\"\\\"}\",\n    \"scene_props\": \"{argument name=\\\"scene_props\\\" description=\\\"Optional surroundings. Defaults to \u0027Curated Studio\u0027.\\\" default=\\\"\\\"}\"\n  },\n\n  \"aesthetic_enforcer\": {\n    \"lighting_setup\": \"Professional studio lighting, soft directional light from left, subtle rim light to separate subject from background, warm reflector fill.\",\n    \"camera_gear\": \"Shot on Phase One XF IQ4 150MP, 80mm Schneider Kreuznach lens, f/2.8 aperture for creamy bokeh.\",\n    \"post_processing\": \"Color graded, high contrast, sharp details, vibrant but natural colors, uncompressed RAW quality.\"\n  },\n\n  \"logic_controller\": {\n    \"scenario_A_image_upload\": {\n      \"check\": \"User provides \u0027source_image\u0027\",\n      \"instruction\": \"Keep the food subject exactly as is, but harmonize the lighting of the GENERATED background to match the \u0027aesthetic_enforcer\u0027 standards. Enhance the surroundings to look like a high-end restaurant or studio.\"\n    },\n    \"scenario_B_text_only\": {\n      \"check\": \"User provides NO image\",\n      \"instruction\": \"Generate the food from scratch. The food MUST look appetizing, glistening, and perfectly plated. Use the \u0027dish_name\u0027 provided. If \u0027scene_props\u0027 is empty, AUTO-SELECT a culturally relevant but \u0027Clean \u0026 Minimal\u0027 background to ensure the food stands out.\"\n    }\n  },\n\n  \"smart_scene_selector\": {\n    \"rule\": \"If \u0027scene_props\u0027 is EMPTY, pick one of these SAFE presets based on dish type:\",\n    \"presets\": [\n      {\n        \"type\": \"Street Food\",\n        \"scene\": \"Clean wooden table, blurred warm market lights in background (bokeh), minimal styling\"\n      },\n      {\n        \"type\": \"Luxury/Fine Dining\",\n        \"scene\": \"Dark textured slate surface, moody lighting, elegant cutlery, wine glass in background\"\n      },\n      {\n        \"type\": \"Cafe/Bakery\",\n        \"scene\": \"White marble top, morning sunlight, soft shadows, fresh flowers in background\"\n      }\n    ]\n  },\n\n  \"final_prompt_structure\": {\n    \"template\": \"A commercial food photography masterpiece of [dish_name OR source_image subject]. Placed in a [mood_tone OR \u0027Sophisticated\u0027] setting featuring [scene_props OR smart_scene_selector result]. \\n\\n**MANDATORY STYLE:** {aesthetic_enforcer.lighting_setup}, {aesthetic_enforcer.camera_gear}, {aesthetic_enforcer.post_processing}. \\n\\n**COMPOSITION:** Rule of thirds, clean background, sharp focus on food texture, no clutter. 8k resolution, highly detailed.\"\n  }\n}",
